<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
final class ProposalDocument extends Model{public$incrementing=false;protected$table='proposal_documents';protected$primaryKey=null;public$timestamps=false;protected$fillable=['proposal_id','document_id','requirement_code','status','document_requirement_version_id','verified_by','verified_at','review_notes'];protected function casts():array{return['verified_at'=>'datetime'];}public function proposal():BelongsTo{return$this->belongsTo(Proposal::class);}public function document():BelongsTo{return$this->belongsTo(Document::class);}public function requirement():BelongsTo{return$this->belongsTo(DocumentRequirementVersion::class,'document_requirement_version_id');}}
